/* dcc_mir_machine_interpreter_runners.c - strict control/interpreter schedules. */

#include "dcc_mir_machine_internal.h"

enum MirInterpreterFileLocationKind {
    MIR_INTERPRETER_FILE_DIRECT,
    MIR_INTERPRETER_FILE_STRUCT,
    MIR_INTERPRETER_FILE_POINTER_STRUCT
};

struct MirInterpreterFileLocation {
    struct Sym *root;
    int offset;
    enum MirInterpreterFileLocationKind kind;
};

enum MirInterpreterFileKind {
    MIR_INTERPRETER_FILE_FORTH,
    MIR_INTERPRETER_FILE_FORTRAN,
    MIR_INTERPRETER_FILE_PREPROCESS_POINTER,
    MIR_INTERPRETER_FILE_COBOL,
    MIR_INTERPRETER_FILE_PASCAL,
    MIR_INTERPRETER_FILE_BASIC,
    MIR_INTERPRETER_FILE_PREPROCESS_STRUCT
};

struct MirInterpreterFileSchedule {
    struct Sym *open_function;
    struct Sym *perror_function;
    struct Sym *seek_function;
    struct Sym *tell_function;
    struct Sym *close_function;
    struct Sym *print_function;
    struct Sym *allocate_function;
    struct Sym *read_function;
    struct Sym *free_function;
    struct Sym *preprocess_function;
    struct Sym *length_function;
    struct MirInterpreterFileLocation source;
    struct MirInterpreterFileLocation source_length;
    enum MirInterpreterFileKind kind;
    int name_stack_offset;
    int mode_string_id;
    int too_large_string_id;
    int allocation_string_id;
    int read_string_id;
    int maximum_source;
    char print_name[64];
};

