    mir_stream_puts("\tld sp,ix\n\tpop ix\n\tret\n", out);
    mir_stream_printf(out, "L%d:\n", scalar);
    mir_cob_emit_call(out, plan, plan->scalar_opcode, -2);
    mir_stream_puts("\tld sp,ix\n\tpop ix\n\tret\n", out);
