static int mir_match_cob_tokenizer_schedule(
    struct MirCobTokenizerSchedule *plan)
{
    static const int statement_members[] = {3, 13, 511};
    static const int token_count_members[] = {9, 517};
    static const int emit_calls[] = {
        140, 145, 205, 210, 268, 272, 428, 431,
        440, 454, 457, 472, 475, 500
    };
    int instruction;
    size_t item;

    memset(plan, 0, sizeof(*plan));
    if (mir.count != 520 || mir_cfg_block_count() != 83 ||
        mir.has_vla || mir.aggregate_temp_bytes != 0 ||
        (mir.return_type & 15) != TYPE_VOID)
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (insn->opcode != mir_cob_tokenizer_opcodes[instruction])
            return 0;
        if ((insn->opcode == MIR_LOAD_INDIRECT ||
             insn->opcode == MIR_STORE_INDIRECT) &&
            (insn->memory_flags & (1 | 8)) != 0)
            return mir_machine_reject(
                "cob-tokenizer-schedule", "volatile-memory");
    }
    if (!mir_machine_parameter_value_offset(
            mir.insns[1].dst, &plan->statement_stack_offset) ||
        type_size(mir.insns[1].type) != 2)
        return mir_machine_reject(
            "cob-tokenizer-schedule", "parameter");
    plan->state = find_global(mir.insns[2].name);
    if (plan->state == NULL || !plan->state->is_defined ||
        plan->state->is_volatile ||
        !mir_cob_member_group(
            plan->state, statement_members,
            sizeof(statement_members) / sizeof(statement_members[0]),
            2, &plan->statements_offset) ||
        !mir_cob_member_group(
            plan->state, token_count_members,
            sizeof(token_count_members) / sizeof(token_count_members[0]),
            2, &plan->token_count_offset))
        return mir_machine_reject(
            "cob-tokenizer-schedule", "state");
    plan->statement_stride = (int)mir.insns[6].immediate;
    plan->statement_start_offset = (int)mir.insns[7].immediate;
    plan->statement_text_offset = (int)mir.insns[17].immediate;
    plan->statement_end_offset = (int)mir.insns[515].immediate;
    if (plan->statement_stride <= 0 ||
        plan->statement_stride > 32 ||
        plan->statement_text_offset < 0 ||
        plan->statement_start_offset < 0 ||
        plan->statement_end_offset < 0 ||
        plan->statement_text_offset + 1 >= plan->statement_stride ||
        plan->statement_start_offset + 1 >= plan->statement_stride ||
        plan->statement_end_offset + 1 >= plan->statement_stride)
        return mir_machine_reject(
            "cob-tokenizer-schedule", "record-layout");
    plan->space_function =
        mir_interpreter_file_function(36, 0, 1);
    plan->emit_function =
        mir_interpreter_file_function(emit_calls[0], 0, 1);
    plan->add_string_function =
        mir_interpreter_file_function(143, 0, 1);
    plan->digit_function =
        mir_interpreter_file_function(158, 0, 1);
    plan->alpha_function =
        mir_interpreter_file_function(278, 0, 1);
    plan->upper_function =
        mir_interpreter_file_function(312, 0, 1);
    plan->alnum_function =
        mir_interpreter_file_function(327, 0, 1);
    plan->keyword_function =
        mir_interpreter_file_function(418, 0, 1);
    plan->find_variable_function =
        mir_interpreter_file_function(445, 0, 1);
    plan->find_paragraph_function =
        mir_interpreter_file_function(463, 0, 1);
    plan->print_function = find_global(mir.insns[486].name);
    if (plan->space_function == NULL ||
        plan->emit_function == NULL ||
        plan->add_string_function == NULL ||
        plan->digit_function == NULL ||
        plan->alpha_function == NULL ||
        plan->upper_function == NULL ||
        plan->alnum_function == NULL ||
        plan->keyword_function == NULL ||
        plan->find_variable_function == NULL ||
        plan->find_paragraph_function == NULL ||
        plan->print_function == NULL ||
        !mir_interpreter_file_same_function(
            plan->digit_function, 182, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->digit_function, 216, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->digit_function, 237, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->upper_function, 398, 0, 1))
        return mir_machine_reject(
            "cob-tokenizer-schedule", "functions");
    for (item = 1;
         item < sizeof(emit_calls) / sizeof(emit_calls[0]);
         ++item)
        if (!mir_interpreter_file_same_function(
                plan->emit_function, emit_calls[item], 0, 1))
            return mir_machine_reject(
                "cob-tokenizer-schedule", "emit-calls");
    plan->unknown_string_id = (int)mir.insns[482].immediate;
    snprintf(
        plan->print_name, sizeof(plan->print_name), "%s",
        mir.insns[486].base_name[0] != 0
            ? mir.insns[486].base_name
            : asm_name_for(sym_asm_name(plan->print_function)));
    {
        const char *exit_name = mir.insns[489].base_name[0] != 0
            ? mir.insns[489].base_name
            : mir.insns[489].name;

        if (exit_name[0] == '_')
            dcc_copy_str(
                plan->exit_name, sizeof(plan->exit_name),
                exit_name);
        else if (strlen(exit_name) + 2 <= sizeof(plan->exit_name)) {
            plan->exit_name[0] = '_';
            dcc_copy_str(
                plan->exit_name + 1,
                sizeof(plan->exit_name) - 1, exit_name);
        }
    }
    if (plan->unknown_string_id < 0 ||
        plan->print_name[0] == 0 ||
        plan->exit_name[0] == 0)
        return mir_machine_reject(
            "cob-tokenizer-schedule", "reports");
    return 1;
}

static void mir_cob_tokenizer_word_address(MirStream *out)
{
    mir_stream_puts("\tpush ix\n\tpop hl\n\tld de,-64\n\tadd hl,de\n",
          out);
}

static void mir_cob_tokenizer_record_address(
    MirStream *out, const struct MirCobTokenizerSchedule *plan)
{
    mir_stream_printf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            plan->statement_stack_offset + 4,
            plan->statement_stack_offset + 5);
    if (plan->statement_stride == 10)
        mir_stream_puts("\tld e,l\n\tld d,h\n\tadd hl,hl\n"
              "\tadd hl,hl\n\tadd hl,de\n\tadd hl,hl\n", out);
    else {
        mir_stream_printf(out, "\tld de,%d\n\tcall __mulu\n",
                plan->statement_stride);
    }
    mir_stream_puts("\tex de,hl\n", out);
    mir_machine_emit_global_word(
        out, plan->state, plan->statements_offset);
    mir_stream_puts("\tadd hl,de\n", out);
}

static void mir_cob_tokenizer_emit(
    MirStream *out, const struct MirCobTokenizerSchedule *plan,
    int value)
{
    mir_stream_printf(out, "\tld hl,%d\n\tpush hl\n", value);
    mir_machine_emit_symbol_call(out, plan->emit_function);
    mir_stream_puts("\tpop bc\n", out);
}

static void mir_cob_tokenizer_emit_local(
    MirStream *out, const struct MirCobTokenizerSchedule *plan,
    int offset)
{
    mir_stream_printf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n",
            offset, offset + 1);
    mir_machine_emit_symbol_call(out, plan->emit_function);
    mir_stream_puts("\tpop bc\n", out);
}

static void mir_cob_tokenizer_call_char(
    MirStream *out, struct Sym *function)
{
    mir_stream_puts("\tld l,(ix-68)\n\tld h,0\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, function);
    mir_stream_puts("\tpop bc\n", out);
}

static void mir_emit_cob_tokenizer_schedule(
    MirStream *out, const struct MirCobTokenizerSchedule *plan)
{
    int loop = new_label();
    int spaces = new_label();
    int have_character = new_label();
    int string_case = new_label();
    int string_loop = new_label();
    int string_done = new_label();
    int string_no_store = new_label();
    int string_no_quote = new_label();
    int negative = new_label();
    int negative_loop = new_label();
    int negative_done = new_label();
    int number = new_label();
    int number_loop = new_label();
    int number_scan = new_label();
    int number_done = new_label();
    int identifier = new_label();
    int identifier_loop = new_label();
    int identifier_done = new_label();
    int identifier_no_store = new_label();
    int identifier_accept = new_label();
    int not_keyword_number = new_label();
    int not_keyword = new_label();
    int not_variable = new_label();
    int not_paragraph = new_label();
    int default_token = new_label();
    int done = new_label();

    mir_stream_puts(MIR_EXACT_KERNEL_MARKER "\n"
          "\tpush iy\n\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-76\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_cob_tokenizer_record_address(out, plan);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->state, plan->token_count_offset);
    mir_stream_puts("\tex de,hl\n\tpop hl\n", out);
    mir_machine_emit_hl_offset(
        out, plan->statement_start_offset, 0);
    mir_stream_puts("\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    mir_cob_tokenizer_record_address(out, plan);
    mir_machine_emit_hl_offset(
        out, plan->statement_text_offset, 0);
    mir_stream_puts("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tpush de\n\tpop iy\n", out);

    mir_stream_printf(out, "L%d:\nL%d:\n\tld a,(iy+0)\n\tor a\n",
            loop, spaces);
    mir_stream_printf(out, "\tjp z,L%d\n\tld (ix-68),a\n", done);
    mir_cob_tokenizer_call_char(out, plan->space_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tinc iy\n\tjp L%d\nL%d:\n",
            have_character, spaces, have_character);
    mir_stream_puts("\tld a,(iy+0)\n\tinc iy\n\tld (ix-68),a\n"
          "\tcp 39\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n", string_case);
    mir_stream_puts("\tcp '-'\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", number);
    mir_stream_puts("\tld a,(iy+0)\n\tld (ix-68),a\n", out);
    mir_cob_tokenizer_call_char(out, plan->digit_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", negative);
    mir_stream_puts("\tld a,'-'\n\tld (ix-68),a\n", out);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", default_token, number);
    mir_stream_puts("\tld a,(ix-68)\n", out);
    mir_cob_tokenizer_call_char(out, plan->digit_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", number_loop);
    mir_stream_puts("\tld a,(ix-68)\n", out);
    mir_cob_tokenizer_call_char(out, plan->alpha_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", identifier);
    mir_stream_puts("\tld a,(ix-68)\n\tcp '_'\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tjp L%d\n",
            identifier, default_token);

    mir_stream_printf(out, "L%d:\n\txor a\n\tld (ix-66),a\nL%d:\n",
            string_case, string_loop);
    mir_stream_puts("\tld a,(iy+0)\n\tor a\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tcp 39\n\tjp z,L%d\n",
            string_done, string_done);
    mir_stream_puts("\tld (ix-68),a\n\tld a,(ix-66)\n\tcp 63\n", out);
    mir_stream_printf(out, "\tjp nc,L%d\n", string_no_store);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tld e,(ix-66)\n\tld d,0\n\tadd hl,de\n"
          "\tld a,(ix-68)\n\tld (hl),a\n\tinc (ix-66)\n",
          out);
    mir_stream_printf(out, "L%d:\n\tinc iy\n\tjp L%d\nL%d:\n",
            string_no_store, string_loop, string_done);
    mir_stream_puts("\tld a,(iy+0)\n\tcp 39\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n\tinc iy\nL%d:\n",
            string_no_quote, string_no_quote);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tld e,(ix-66)\n\tld d,0\n\tadd hl,de\n"
          "\tld (hl),0\n", out);
    mir_cob_tokenizer_emit(out, plan, 257);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->add_string_function);
    mir_stream_puts("\tpop bc\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->emit_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "\tjp L%d\n", loop);

    mir_stream_printf(out, "L%d:\n\txor a\n\tld (ix-76),a\n"
            "\tld (ix-75),a\nL%d:\n",
            negative, negative_loop);
    mir_stream_puts("\tld a,(iy+0)\n\tld (ix-68),a\n", out);
    mir_cob_tokenizer_call_char(out, plan->digit_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n", negative_done);
    mir_interpreter_file_load_ix_word(out, -76);
    mir_stream_puts("\tld de,0\n\tld e,l\n\tld d,h\n"
          "\tadd hl,hl\n\tadd hl,hl\n\tadd hl,de\n"
          "\tadd hl,hl\n\tld a,(ix-68)\n\tsub '0'\n"
          "\tld e,a\n\tld d,0\n\tadd hl,de\n", out);
    mir_interpreter_file_store_ix_word(out, -76);
    mir_stream_puts("\tinc iy\n", out);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", negative_loop, negative_done);
    mir_cob_tokenizer_emit(out, plan, 256);
    mir_interpreter_file_load_ix_word(out, -76);
    mir_stream_puts("\txor a\n\tsub l\n\tld l,a\n"
          "\tld a,0\n\tsbc a,h\n\tld h,a\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->emit_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "\tjp L%d\n", loop);

    mir_stream_printf(out, "L%d:\n", number_loop);
    mir_stream_puts("\tld a,(ix-68)\n\tsub '0'\n\tld l,a\n\tld h,0\n",
          out);
    mir_interpreter_file_store_ix_word(out, -76);
    mir_stream_printf(out, "L%d:\n\tld a,(iy+0)\n\tor a\n",
            number_scan);
    mir_stream_printf(out, "\tjp z,L%d\n\tld (ix-68),a\n", number_done);
    mir_cob_tokenizer_call_char(out, plan->digit_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n", number_done);
    mir_interpreter_file_load_ix_word(out, -76);
    mir_stream_puts("\tld de,0\n\tld e,l\n\tld d,h\n"
          "\tadd hl,hl\n\tadd hl,hl\n\tadd hl,de\n"
          "\tadd hl,hl\n\tld a,(ix-68)\n\tsub '0'\n"
          "\tld e,a\n\tld d,0\n\tadd hl,de\n", out);
    mir_interpreter_file_store_ix_word(out, -76);
    mir_stream_puts("\tinc iy\n", out);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", number_scan, number_done);
    mir_cob_tokenizer_emit(out, plan, 256);
    mir_cob_tokenizer_emit_local(out, plan, -76);
    mir_stream_printf(out, "\tjp L%d\n", loop);

    mir_stream_printf(out, "L%d:\n\txor a\n\tld (ix-66),a\n"
            "\tld a,(ix-68)\n", identifier);
    mir_cob_tokenizer_call_char(out, plan->upper_function);
    mir_stream_puts("\tld (ix-68),l\n", out);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tld a,(ix-68)\n\tld (hl),a\n\tinc (ix-66)\n", out);
    mir_stream_printf(out, "L%d:\n\tld a,(iy+0)\n\tor a\n",
            identifier_loop);
    mir_stream_printf(out, "\tjp z,L%d\n\tld (ix-68),a\n",
            identifier_done);
    mir_cob_tokenizer_call_char(out, plan->alnum_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", identifier_accept);
    mir_stream_puts("\tld a,(ix-68)\n\tcp '-'\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tcp '_'\n\tjp nz,L%d\nL%d:\n",
            identifier_accept, identifier_done, identifier_accept);
    mir_stream_puts("\tld a,(ix-66)\n\tcp 63\n", out);
    mir_stream_printf(out, "\tjp nc,L%d\n", identifier_no_store);
    mir_stream_puts("\tld a,(ix-68)\n", out);
    mir_cob_tokenizer_call_char(out, plan->upper_function);
    mir_stream_puts("\tld (ix-68),l\n", out);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tld e,(ix-66)\n\tld d,0\n\tadd hl,de\n"
          "\tld a,(ix-68)\n\tld (hl),a\n\tinc (ix-66)\n", out);
    mir_stream_printf(out, "L%d:\n\tinc iy\n\tjp L%d\nL%d:\n",
            identifier_no_store, identifier_loop, identifier_done);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tld e,(ix-66)\n\tld d,0\n\tadd hl,de\n\tld (hl),0\n",
          out);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->keyword_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_interpreter_file_store_ix_word(out, -70);
    mir_stream_puts("\tld de,256\n\tor a\n\tsbc hl,de\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", not_keyword_number);
    mir_cob_tokenizer_emit(out, plan, 256);
    mir_cob_tokenizer_emit(out, plan, 0);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", loop, not_keyword_number);
    mir_interpreter_file_load_ix_word(out, -70);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n", not_keyword);
    mir_cob_tokenizer_emit_local(out, plan, -70);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", loop, not_keyword);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->find_variable_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_interpreter_file_store_ix_word(out, -72);
    mir_stream_puts("\tbit 7,h\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", not_variable);
    mir_cob_tokenizer_emit(out, plan, 258);
    mir_cob_tokenizer_emit_local(out, plan, -72);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", loop, not_variable);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->find_paragraph_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_interpreter_file_store_ix_word(out, -74);
    mir_stream_puts("\tbit 7,h\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", not_paragraph);
    mir_cob_tokenizer_emit(out, plan, 259);
    mir_cob_tokenizer_emit_local(out, plan, -74);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", loop, not_paragraph);
    mir_cob_tokenizer_word_address(out);
    mir_stream_puts("\tpush hl\n", out);
    mir_stream_printf(out, "\tld hl,S%d\n\tpush hl\n\tld hl,2\n\tpush hl\n",
            plan->unknown_string_id);
    mir_emit_runtime_call(out, plan->print_name);
    mir_interpreter_file_cleanup(out, 3);
    mir_stream_puts("\tld hl,1\n\tpush hl\n", out);
    mir_emit_runtime_call(out, plan->exit_name);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n",
            loop, default_token);
    mir_stream_puts("\tld l,(ix-68)\n\tld h,0\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->emit_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", loop, done);
    mir_cob_tokenizer_record_address(out, plan);
    mir_machine_emit_hl_offset(out, plan->statement_end_offset, 0);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->state, plan->token_count_offset);
    mir_stream_puts("\tex de,hl\n\tpop hl\n"
          "\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
          "\tld sp,ix\n\tpop ix\n\tpop iy\n\tret\n", out);
}

static int mir_match_cob_perform_schedule(
    struct MirCobPerformSchedule *plan)
{
    static const int position_members[] = {
        2, 8, 23, 38, 44, 59, 87, 102, 113, 128, 143, 158,
        164, 179, 194, 209, 220, 226, 241, 254, 269, 280,
        303, 318, 329, 347, 362, 377, 383, 398, 411, 426,
        437, 459, 474, 485, 507, 522, 533
    };
    static const int end_members[] = {
        11, 47, 90, 131, 167, 197, 229,
        257, 306, 350, 386, 414, 462, 510
    };
    static const int token_members[] = {
        20, 56, 99, 140, 176, 206, 238,
        266, 315, 359, 395, 423, 471, 519
    };
    static const int code_position_members[] = {563, 578};
    static const int perform_count_members[] = {585, 595};
    static const int performs_members[] = {
        603, 611, 619, 627, 635, 643
    };
    static const int field_members[] = {
        607, 615, 623, 631, 639, 647
    };
    static const int error_insns[] = {33, 153, 372, 452, 590};
    int instruction;
    int field;

    memset(plan, 0, sizeof(*plan));
    if (mir.count != 657 || mir_cfg_block_count() != 92 ||
        mir.has_vla || mir.aggregate_temp_bytes != 0 ||
        (mir.return_type & 15) != TYPE_VOID)
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if ((insn->opcode == MIR_LOAD_INDIRECT ||
             insn->opcode == MIR_STORE_INDIRECT) &&
            (insn->memory_flags & (1 | 8)) != 0)
            return mir_machine_reject(
                "cob-perform-schedule", "volatile-memory");
    }
    plan->state = find_global(mir.insns[1].name);
    if (plan->state == NULL || !plan->state->is_defined ||
        plan->state->is_volatile ||
        !mir_cob_member_group(
            plan->state, position_members,
            sizeof(position_members) / sizeof(position_members[0]),
            2, &plan->token_position_offset) ||
        !mir_cob_member_group(
            plan->state, end_members,
            sizeof(end_members) / sizeof(end_members[0]),
            2, &plan->token_end_offset) ||
        !mir_cob_member_group(
            plan->state, token_members,
            sizeof(token_members) / sizeof(token_members[0]),
            2, &plan->tokens_offset) ||
        !mir_cob_member_group(
            plan->state, code_position_members,
            sizeof(code_position_members) /
                sizeof(code_position_members[0]),
            2, &plan->code_position_offset) ||
        !mir_cob_member_group(
            plan->state, perform_count_members,
            sizeof(perform_count_members) /
                sizeof(perform_count_members[0]),
            2, &plan->perform_count_offset) ||
        !mir_cob_member_group(
            plan->state, performs_members,
            sizeof(performs_members) / sizeof(performs_members[0]),
            2, &plan->performs_offset))
        return mir_machine_reject(
            "cob-perform-schedule", "state");
    plan->failure_function =
        mir_interpreter_file_function(35, 0, 1);
    plan->expression_function =
        mir_interpreter_file_function(457, 0, 0);
    plan->emit_function =
        mir_interpreter_file_function(559, 0, 3);
    plan->condition_function =
        mir_interpreter_file_function(567, 0, 0);
    plan->patch_function =
        mir_interpreter_file_function(581, 0, 2);
    if (plan->failure_function == NULL ||
        plan->expression_function == NULL ||
        plan->emit_function == NULL ||
        plan->condition_function == NULL ||
        plan->patch_function == NULL ||
        !mir_interpreter_file_same_function(
            plan->failure_function, 155, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->failure_function, 297, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->failure_function, 374, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->failure_function, 454, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->failure_function, 502, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->failure_function, 550, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->expression_function, 505, 0, 0) ||
        !mir_interpreter_file_same_function(
            plan->emit_function, 574, 0, 3) ||
        !mir_interpreter_file_same_function(
            plan->emit_function, 656, 0, 3))
        return mir_machine_reject(
            "cob-perform-schedule", "functions");
    for (field = 0; field < 5; ++field) {
        if (mir.insns[error_insns[field]].immediate < 0)
            return mir_machine_reject(
                "cob-perform-schedule", "strings");
        plan->error_strings[field] =
            (int)mir.insns[error_insns[field]].immediate;
    }
    plan->perform_stride = (int)mir.insns[606].immediate;
    if (plan->perform_stride <= 0 || plan->perform_stride > 32)
        return mir_machine_reject(
            "cob-perform-schedule", "perform-stride");
    for (field = 0; field < 6; ++field) {
        const struct MirInsn *member = &mir.insns[field_members[field]];

        if (member->opcode != MIR_MEMBER_ADDRESS ||
            member->memory_size != 2 ||
            member->immediate < 0 ||
            member->immediate + 1 >= plan->perform_stride)
            return mir_machine_reject(
                "cob-perform-schedule", "perform-fields");
        plan->perform_field_offsets[field] =
            (int)member->immediate;
    }
    return 1;
}

static void mir_cob_perform_access(
    struct MirCobAddSubSchedule *access,
    const struct MirCobPerformSchedule *plan)
{
    memset(access, 0, sizeof(*access));
    access->state = plan->state;
    access->token_position_offset = plan->token_position_offset;
    access->token_end_offset = plan->token_end_offset;
    access->tokens_offset = plan->tokens_offset;
    access->failure_function = plan->failure_function;
}

static void mir_cob_perform_emit(
    MirStream *out, const struct MirCobPerformSchedule *plan,
    int opcode, int value_offset)
{
    mir_stream_puts("\tld hl,0\n\tpush hl\n", out);
    if (value_offset != 0)
        mir_stream_printf(out,
                "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
                value_offset, value_offset + 1);
    mir_stream_puts("\tpush hl\n", out);
    mir_stream_printf(out, "\tld hl,%d\n\tpush hl\n", opcode);
    mir_machine_emit_symbol_call(out, plan->emit_function);
    mir_interpreter_file_cleanup(out, 3);
}

static void mir_cob_perform_record_address(
    MirStream *out, const struct MirCobPerformSchedule *plan,
    int field)
{
    mir_machine_emit_global_word(
        out, plan->state, plan->performs_offset);
    mir_stream_puts("\tpush hl\n", out);
    mir_stream_puts("\tld l,(ix-12)\n\tld h,(ix-11)\n", out);
    if (plan->perform_stride == 12)
        mir_stream_puts("\tld e,l\n\tld d,h\n\tadd hl,hl\n"
              "\tadd hl,de\n\tadd hl,hl\n\tadd hl,hl\n", out);
    else {
        mir_stream_printf(out, "\tld de,%d\n\tcall __mulu\n",
                plan->perform_stride);
    }
    mir_stream_puts("\tpop de\n\tadd hl,de\n", out);
    mir_machine_emit_hl_offset(
        out, plan->perform_field_offsets[field], 0);
}

static void mir_cob_perform_store_field(
    MirStream *out, const struct MirCobPerformSchedule *plan,
    int field, int local_offset)
{
    mir_cob_perform_record_address(out, plan, field);
    mir_stream_printf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
            local_offset, local_offset + 1);
}

static void mir_cob_perform_require_local(
    MirStream *out, const struct MirCobPerformSchedule *plan,
    int peek_label, int increment_label,
    int token, int string_id)
{
    int matched = new_label();

    mir_stream_printf(out,
            "\tcall L%d\n\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp z,L%d\n\tld hl,S%d\n\tpush hl\n",
            peek_label, token, matched, string_id);
    mir_machine_emit_symbol_call(out, plan->failure_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "L%d:\n\tcall L%d\n",
            matched, increment_label);
}

static void mir_emit_cob_perform_schedule(
    MirStream *out, const struct MirCobPerformSchedule *plan)
{
    int have_paragraph = new_label();
    int no_thru = new_label();
    int have_thru = new_label();
    int no_count = new_label();
    int no_varying = new_label();
    int have_variable = new_label();
    int have_capacity = new_label();
    int peek_helper = new_label();
    int increment_helper = new_label();
    int get_helper = new_label();

    mir_stream_puts(MIR_EXACT_KERNEL_MARKER "\n"
          "\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-16\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_stream_printf(out, "\tcall L%d\n\tcall L%d\n",
            increment_helper, peek_helper);
    mir_stream_puts("\tld de,259\n\tor a\n\tsbc hl,de\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tld hl,S%d\n\tpush hl\n",
            have_paragraph, plan->error_strings[0]);
    mir_machine_emit_symbol_call(out, plan->failure_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "L%d:\n", have_paragraph);
    mir_stream_printf(out, "\tcall L%d\n\tcall L%d\n",
            increment_helper, get_helper);
    mir_interpreter_file_store_ix_word(out, -2);
    mir_interpreter_file_store_ix_word(out, -4);
    mir_stream_puts("\tld hl,1\n", out);
    mir_interpreter_file_store_ix_word(out, -10);
    mir_stream_puts("\tld hl,0\n", out);
    mir_interpreter_file_store_ix_word(out, -8);
    mir_interpreter_file_store_ix_word(out, -6);
    mir_interpreter_file_store_ix_word(out, -16);

    mir_stream_printf(out, "\tcall L%d\n", peek_helper);
    mir_stream_puts("\tld de,312\n\tor a\n\tsbc hl,de\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", no_thru);
    mir_stream_printf(out, "\tcall L%d\n\tcall L%d\n",
            increment_helper, peek_helper);
    mir_stream_puts("\tld de,259\n\tor a\n\tsbc hl,de\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tld hl,S%d\n\tpush hl\n",
            have_thru, plan->error_strings[1]);
    mir_machine_emit_symbol_call(out, plan->failure_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "L%d:\n", have_thru);
    mir_stream_printf(out, "\tcall L%d\n\tcall L%d\n",
            increment_helper, get_helper);
    mir_interpreter_file_store_ix_word(out, -4);
    mir_stream_printf(out, "L%d:\n", no_thru);

    mir_stream_printf(out, "\tcall L%d\n", peek_helper);
    mir_stream_puts("\tld de,256\n\tor a\n\tsbc hl,de\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", no_count);
    mir_stream_printf(out, "\tcall L%d\n\tcall L%d\n",
            increment_helper, get_helper);
    mir_interpreter_file_store_ix_word(out, -10);
    mir_cob_perform_require_local(
        out, plan, peek_helper, increment_helper,
        313, plan->error_strings[3]);
    mir_stream_printf(out, "L%d:\n", no_count);

    mir_stream_printf(out, "\tcall L%d\n", peek_helper);
    mir_stream_puts("\tld de,314\n\tor a\n\tsbc hl,de\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", no_varying);
    mir_stream_printf(out, "\tcall L%d\n", increment_helper);
    mir_stream_puts("\tld hl,1\n", out);
    mir_interpreter_file_store_ix_word(out, -8);
    mir_stream_printf(out, "\tcall L%d\n", peek_helper);
    mir_stream_puts("\tld de,258\n\tor a\n\tsbc hl,de\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tld hl,S%d\n\tpush hl\n",
            have_variable, plan->error_strings[2]);
    mir_machine_emit_symbol_call(out, plan->failure_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "L%d:\n", have_variable);
    mir_stream_printf(out, "\tcall L%d\n\tcall L%d\n",
            increment_helper, get_helper);
    mir_interpreter_file_store_ix_word(out, -6);
    mir_cob_perform_require_local(
        out, plan, peek_helper, increment_helper,
        305, plan->error_strings[3]);
    mir_machine_emit_symbol_call(out, plan->expression_function);
    mir_cob_perform_require_local(
        out, plan, peek_helper, increment_helper,
        307, plan->error_strings[3]);
    mir_machine_emit_symbol_call(out, plan->expression_function);
    mir_cob_perform_require_local(
        out, plan, peek_helper, increment_helper,
        315, plan->error_strings[3]);
    mir_cob_perform_emit(out, plan, 25, 0);
    mir_interpreter_file_store_ix_word(out, -14);
    mir_machine_emit_global_word(
        out, plan->state, plan->code_position_offset);
    mir_interpreter_file_store_ix_word(out, -16);
    mir_machine_emit_symbol_call(out, plan->condition_function);
    mir_cob_perform_emit(out, plan, 1, 0);
    mir_machine_emit_global_word(
        out, plan->state, plan->code_position_offset);
    mir_stream_puts("\tpush hl\n", out);
    mir_interpreter_file_load_ix_word(out, -14);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->patch_function);
    mir_interpreter_file_cleanup(out, 2);
    mir_stream_printf(out, "L%d:\n", no_varying);

    mir_machine_emit_global_word(
        out, plan->state, plan->perform_count_offset);
    mir_stream_puts("\tld de,32\n\tor a\n\tsbc hl,de\n", out);
    mir_stream_printf(out, "\tjp c,L%d\n\tld hl,S%d\n\tpush hl\n",
            have_capacity, plan->error_strings[4]);
    mir_machine_emit_symbol_call(out, plan->failure_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "L%d:\n", have_capacity);
    mir_machine_emit_global_word(
        out, plan->state, plan->perform_count_offset);
    mir_interpreter_file_store_ix_word(out, -12);
    mir_stream_puts("\tinc hl\n", out);
    mir_machine_emit_global_word_store(
        out, plan->state, plan->perform_count_offset);
    mir_cob_perform_store_field(out, plan, 0, -2);
    mir_cob_perform_store_field(out, plan, 1, -4);
    mir_cob_perform_store_field(out, plan, 2, -8);
    mir_cob_perform_store_field(out, plan, 3, -10);
    mir_cob_perform_store_field(out, plan, 4, -6);
    mir_cob_perform_store_field(out, plan, 5, -16);
    mir_cob_perform_emit(out, plan, 34, -12);
    mir_stream_puts("\tld sp,ix\n\tpop ix\n\tret\n", out);
    mir_stream_printf(out, "L%d:\n", peek_helper);
    {
        struct MirCobAddSubSchedule access;

        mir_cob_perform_access(&access, plan);
        mir_cob_peek(out, &access);
    }
    mir_stream_puts("\tret\n", out);
    mir_stream_printf(out, "L%d:\n", increment_helper);
    mir_machine_emit_global_word(
        out, plan->state, plan->token_position_offset);
    mir_stream_puts("\tinc hl\n", out);
    mir_machine_emit_global_word_store(
        out, plan->state, plan->token_position_offset);
    mir_stream_puts("\tret\n", out);
    mir_stream_printf(out, "L%d:\n\tcall L%d\n\tpush hl\n"
            "\tcall L%d\n\tpop hl\n\tret\n",
            get_helper, peek_helper, increment_helper);
}

static int mir_match_cob_chain_schedule(
    struct MirCobChainSchedule *plan)
{
    static const int position_members[] = {4, 19, 34, 49, 72, 87};
    static const int condition_position_members[] = {
        4, 19, 34, 49, 72, 87, 99
    };
    static const int end_members[] = {7, 37, 75};
    static const int token_members[] = {16, 46, 84};
    const int *positions;
    size_t position_count;
    int second_child;
    int emit_instruction;
    int first_opcode_instruction;
    int second_opcode_instruction;
    long value;

    memset(plan, 0, sizeof(*plan));
    if ((mir.count != 122 && mir.count != 125) ||
        mir_cfg_block_count() != 27 ||
        mir.has_vla || mir.aggregate_temp_bytes != 0 ||
        (mir.return_type & 15) != TYPE_VOID)
        return 0;
    positions = mir.count == 125
        ? condition_position_members : position_members;
    position_count = mir.count == 125
        ? sizeof(condition_position_members) /
              sizeof(condition_position_members[0])
        : sizeof(position_members) / sizeof(position_members[0]);
    second_child = mir.count == 125 ? 104 : 99;
    emit_instruction = mir.count == 125 ? 120 : 117;
    first_opcode_instruction = mir.count == 125 ? 107 : 104;
    second_opcode_instruction = mir.count == 125 ? 111 : 108;
    plan->state = find_global(mir.insns[3].name);
    if (plan->state == NULL || !plan->state->is_defined ||
        plan->state->is_volatile ||
        !mir_cob_member_group(
            plan->state, positions, position_count,
            2, &plan->token_position_offset) ||
        !mir_cob_member_group(
            plan->state, end_members,
            sizeof(end_members) / sizeof(end_members[0]),
            2, &plan->token_end_offset) ||
        !mir_cob_member_group(
            plan->state, token_members,
            sizeof(token_members) / sizeof(token_members[0]),
            2, &plan->tokens_offset))
        return 0;
    plan->child_function =
        mir_interpreter_file_function(1, 0, 0);
    plan->emit_function =
        mir_interpreter_file_function(emit_instruction, 0, 3);
    if (plan->child_function == NULL ||
        plan->emit_function == NULL ||
        !mir_interpreter_file_same_function(
            plan->child_function, second_child, 0, 0))
        return 0;
    if (!mir_machine_evaluate_constant(
            mir.insns[26].dst, &value, 0))
        return 0;
    plan->first_token = (int)value;
    if (!mir_machine_evaluate_constant(
            mir.insns[56].dst, &value, 0))
        return 0;
    plan->second_token = (int)value;
    if (!mir_machine_evaluate_constant(
            mir.insns[first_opcode_instruction].dst,
            &value, 0))
        return 0;
    plan->first_opcode = (int)value;
    if (!mir_machine_evaluate_constant(
            mir.insns[second_opcode_instruction].dst,
            &value, 0))
        return 0;
    plan->second_opcode = (int)value;
    return plan->first_token != plan->second_token &&
           plan->first_opcode != plan->second_opcode;
}

static void mir_emit_cob_chain_schedule(
    MirStream *out, const struct MirCobChainSchedule *plan)
{
    struct MirCobAddSubSchedule access;
    int loop = new_label();
    int second = new_label();
    int done = new_label();
    int emit = new_label();

    memset(&access, 0, sizeof(access));
    access.state = plan->state;
    access.token_position_offset = plan->token_position_offset;
    access.token_end_offset = plan->token_end_offset;
    access.tokens_offset = plan->tokens_offset;
    access.emit_function = plan->emit_function;
    mir_stream_puts(MIR_EXACT_KERNEL_MARKER "\n"
          "\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tdec sp\n\tdec sp\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_machine_emit_symbol_call(out, plan->child_function);
    mir_stream_printf(out, "L%d:\n", loop);
    mir_cob_peek(out, &access);
    mir_stream_printf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nz,L%d\n\tld hl,%d\n\tjp L%d\n"
            "L%d:\n",
            plan->first_token, second,
            plan->first_opcode, emit, second);
    mir_cob_peek(out, &access);
    mir_stream_printf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nz,L%d\n\tld hl,%d\n"
            "L%d:\n",
            plan->second_token, done,
            plan->second_opcode, emit);
    mir_interpreter_file_store_ix_word(out, -2);
    mir_cob_increment_token_position(out, &access);
    mir_machine_emit_symbol_call(out, plan->child_function);
    mir_stream_puts("\tld hl,0\n\tpush hl\n\tpush hl\n"
          "\tld l,(ix-2)\n\tld h,(ix-1)\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->emit_function);
    mir_interpreter_file_cleanup(out, 3);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            loop, done);
}

static int mir_match_fortran_statement_append_schedule(
    struct MirFortranStatementAppendSchedule *plan)
{
    static const int member_indices[8] = {
        15, 21, 29, 35, 42, 49, 56, 63
    };
    int instruction;
    int member;

    memset(plan, 0, sizeof(*plan));
    if (mir.count != 71 || mir_cfg_block_count() != 2 ||
        mir.has_vla || mir.aggregate_temp_bytes != 0 ||
        (mir.return_type & 15) != TYPE_VOID ||
        mir.insns[7].label != mir.insns[11].label)
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction)
        if (mir.insns[instruction].opcode !=
                mir_fortran_add_stmt_opcodes[instruction])
            return 0;
    if (!mir_machine_parameter_value_offset(
            mir.insns[1].dst, &plan->label_stack_offset) ||
        !mir_machine_parameter_value_offset(
            mir.insns[2].dst, &plan->text_stack_offset) ||
        !mir_machine_parameter_value_offset(
            mir.insns[3].dst, &plan->unit_stack_offset) ||
        plan->text_stack_offset != plan->label_stack_offset + 2 ||
        plan->unit_stack_offset != plan->text_stack_offset + 2)
        return mir_machine_reject(
            "fortran-statement-append", "parameters");
    plan->statement_count =
        mir_pascal_scan_symbol(4, 2, 0);
    plan->statements =
        mir_pascal_scan_symbol(12, 2, 0);
    plan->failure_function = find_global(mir.insns[10].name);
    plan->duplicate_function =
        mir_interpreter_file_function(24, 0, 1);
    plan->failure_string_id = (int)mir.insns[8].immediate;
    plan->limit = (int)mir.insns[5].immediate;
    plan->stride = (int)mir.insns[14].immediate;
    if (plan->statement_count == NULL ||
        plan->statements == NULL ||
        plan->failure_function == NULL ||
        plan->duplicate_function == NULL ||
        plan->failure_string_id < 0 ||
        plan->limit <= 0 || plan->limit > 32767 ||
        plan->stride <= 0 || plan->stride > 128)
        return mir_machine_reject(
            "fortran-statement-append", "symbols");
    for (member = 0; member < 8; ++member) {
        const struct MirInsn *insn =
            &mir.insns[member_indices[member]];

        if (insn->opcode != MIR_MEMBER_ADDRESS ||
            insn->memory_size != 2 ||
            insn->immediate < 0 ||
            insn->immediate + 1 >= plan->stride)
            return mir_machine_reject(
                "fortran-statement-append", "members");
        plan->offsets[member] = (int)insn->immediate;
    }
    if (!mir_pascal_scan_same_symbol(plan->statements, 18) ||
        !mir_pascal_scan_same_symbol(plan->statements, 26) ||
        !mir_pascal_scan_same_symbol(plan->statements, 32) ||
        !mir_pascal_scan_same_symbol(plan->statement_count, 13) ||
        !mir_pascal_scan_same_symbol(plan->statement_count, 19) ||
        !mir_pascal_scan_same_symbol(plan->statement_count, 27) ||
        !mir_machine_constant_equals(mir.insns[37].dst, 65535) ||
        !mir_machine_constant_equals(mir.insns[44].dst, 65535) ||
        !mir_machine_constant_equals(mir.insns[51].dst, 65535) ||
        !mir_machine_constant_equals(mir.insns[58].dst, 65535) ||
        !mir_machine_constant_equals(mir.insns[65].dst, 65535) ||
        !mir_machine_constant_equals(mir.insns[68].dst, 1))
        return mir_machine_reject(
            "fortran-statement-append", "semantics");
    return 1;
}

static void mir_fortran_statement_address(
    MirStream *out, const struct MirFortranStatementAppendSchedule *plan)
{
    mir_machine_emit_global_word(out, plan->statement_count, 0);
    if (plan->stride == 62) {
        mir_stream_puts("\tld e,l\n\tld d,h\n\tadd hl,hl\n"
              "\tadd hl,hl\n\tadd hl,hl\n\tadd hl,de\n"
              "\tadd hl,hl\n\tadd hl,hl\n\tadd hl,de\n"
              "\tadd hl,hl\n", out);
    } else {
        mir_stream_printf(out, "\tld de,%d\n\tcall __mulu\n",
                plan->stride);
    }
    mir_stream_puts("\tex de,hl\n", out);
    mir_machine_emit_global_word(out, plan->statements, 0);
    mir_stream_puts("\tadd hl,de\n", out);
}

static void mir_fortran_store_member(
    MirStream *out, const struct MirFortranStatementAppendSchedule *plan,
    int address_label, int member, int stack_offset, int constant)
{
    mir_stream_printf(out, "\tcall L%d\n", address_label);
    mir_machine_emit_hl_offset(out, plan->offsets[member], 0);
    if (stack_offset != 0)
        mir_stream_printf(out,
                "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
                stack_offset, stack_offset + 1);
    else
        mir_stream_printf(out, "\tld de,%d\n", constant);
    mir_stream_puts("\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
}

static void mir_emit_fortran_statement_append_schedule(
    MirStream *out, const struct MirFortranStatementAppendSchedule *plan)
{
    int room = new_label();
    int address_helper = new_label();

    mir_stream_puts(MIR_EXACT_KERNEL_MARKER "\n"
          "\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_machine_emit_global_word(out, plan->statement_count, 0);
    mir_stream_printf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp c,L%d\n\tld hl,S%d\n\tpush hl\n",
            plan->limit, room, plan->failure_string_id);
    mir_machine_emit_symbol_call(out, plan->failure_function);
    mir_stream_puts("\tpop bc\n", out);
    mir_stream_printf(out, "L%d:\n", room);
    mir_fortran_store_member(
        out, plan, address_helper, 0,
        plan->label_stack_offset + 2, 0);
    mir_stream_printf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n",
            plan->text_stack_offset + 2,
            plan->text_stack_offset + 3);
    mir_machine_emit_symbol_call(out, plan->duplicate_function);
    mir_stream_puts("\tpop bc\n\tpush hl\n", out);
    mir_stream_printf(out, "\tcall L%d\n", address_helper);
    mir_machine_emit_hl_offset(out, plan->offsets[1], 0);
    mir_stream_puts("\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    mir_fortran_store_member(
        out, plan, address_helper, 2,
        plan->unit_stack_offset + 2, 0);
    mir_fortran_store_member(
        out, plan, address_helper, 3, 0, -1);
    mir_fortran_store_member(
        out, plan, address_helper, 4, 0, -1);
    mir_fortran_store_member(
        out, plan, address_helper, 5, 0, -1);
    mir_fortran_store_member(
        out, plan, address_helper, 6, 0, -1);
    mir_fortran_store_member(
        out, plan, address_helper, 7, 0, -1);
    mir_machine_emit_global_word(out, plan->statement_count, 0);
    mir_stream_puts("\tinc hl\n", out);
    mir_machine_emit_global_word_store(
        out, plan->statement_count, 0);
    mir_stream_puts("\tpop ix\n\tret\n", out);
    mir_stream_printf(out, "L%d:\n", address_helper);
    mir_fortran_statement_address(out, plan);
    mir_stream_puts("\tret\n", out);
}

static int mir_match_fortran_uppercase_schedule(
    struct MirFortranUppercaseSchedule *plan)
{
    static const unsigned char expected_opcodes[55] = {
        MIR_LABEL, MIR_PARAM, MIR_PARAM, MIR_CONST, MIR_NOP,
        MIR_STORE, MIR_LABEL, MIR_NOP, MIR_NOP, MIR_PHI,
        MIR_NOP, MIR_NOP, MIR_INDEX_ADDRESS, MIR_LOAD_INDIRECT,
        MIR_BRANCH_FALSE, MIR_NOP, MIR_NOP, MIR_NOP, MIR_CONST,
        MIR_BINARY, MIR_BRANCH_FALSE, MIR_LABEL, MIR_CONST,
        MIR_JUMP, MIR_LABEL, MIR_CONST, MIR_LABEL, MIR_PHI,
        MIR_BRANCH_FALSE, MIR_NOP, MIR_NOP, MIR_INDEX_ADDRESS,
        MIR_NOP, MIR_NOP, MIR_INDEX_ADDRESS, MIR_LOAD_INDIRECT,
        MIR_UNARY, MIR_UNARY, MIR_ARG, MIR_CALL, MIR_UNARY,
        MIR_STORE_INDIRECT, MIR_LABEL, MIR_NOP, MIR_CONST,
        MIR_BINARY, MIR_STORE, MIR_JUMP, MIR_LABEL, MIR_NOP,
        MIR_NOP, MIR_INDEX_ADDRESS, MIR_NOP, MIR_CONST,
        MIR_STORE_INDIRECT
    };
    struct Sym *uppercase_function;
    int arguments[1];
    int instruction;
    long limit;

    memset(plan, 0, sizeof(*plan));
    if (mir.count != 55 || mir.next_value != 38 ||
        mir_cfg_block_count() != 7 || mir.local_bytes != 2 ||
        mir.aggregate_temp_bytes != 0 || mir.has_vla ||
        !mir_has_cfg_backedge() ||
        (mir.return_type & 15) != TYPE_VOID)
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction)
        if (mir.insns[instruction].opcode !=
            expected_opcodes[instruction])
            return mir_machine_reject(
                "fortran-uppercase", "opcodes");
    if (!mir_machine_parameter_value_offset(
            mir.insns[1].dst,
            &plan->destination_stack_offset) ||
        !mir_machine_parameter_value_offset(
            mir.insns[2].dst,
            &plan->source_stack_offset) ||
        plan->destination_stack_offset != 2 ||
        plan->source_stack_offset != 4 ||
        type_ptr_depth(mir.insns[1].type) != 1 ||
        type_ptr_depth(mir.insns[2].type) != 1 ||
        (mir.insns[1].type & 15) != TYPE_CHAR ||
        (mir.insns[2].type & 15) != TYPE_CHAR ||
        type_size(mir.insns[1].type) != 2 ||
        type_size(mir.insns[2].type) != 2 ||
        mir_machine_pointee_is_volatile(&mir.insns[1]) ||
        mir_machine_pointee_is_volatile(&mir.insns[2]))
        return mir_machine_reject(
            "fortran-uppercase", "parameters");
    if (!mir_machine_constant_equals(mir.insns[3].dst, 0) ||
        !mir_machine_unobservable_local_store(&mir.insns[5]) ||
        mir.insns[5].src1 != mir.insns[3].dst ||
        mir.insns[9].src1 != mir.insns[3].dst ||
        mir.insns[9].src2 != mir.insns[45].dst ||
        mir.insns[9].phi_pred1 != mir.insns[0].label ||
        mir.insns[9].phi_pred2 != mir.insns[42].label ||
        mir.insns[9].object != mir.insns[5].object ||
        mir.insns[12].src1 != mir.insns[2].dst ||
        mir.insns[12].src2 != mir.insns[9].dst ||
        mir.insns[12].immediate != 1 ||
        mir.insns[12].memory_size != 1 ||
        mir.insns[13].src1 != mir.insns[12].dst ||
        mir.insns[13].memory_size != 1 ||
        mir.insns[14].src1 != mir.insns[13].dst ||
        mir.insns[14].label != mir.insns[24].label ||
        !mir_machine_evaluate_constant(
            mir.insns[18].dst, &limit, 0) ||
        limit <= 0 || limit > 255 ||
        mir.insns[19].src1 != mir.insns[9].dst ||
        mir.insns[19].src2 != mir.insns[18].dst ||
        mir.insns[19].immediate != '<' ||
        mir.insns[20].src1 != mir.insns[19].dst ||
        mir.insns[20].label != mir.insns[24].label ||
        !mir_machine_constant_equals(mir.insns[22].dst, 1) ||
        !mir_machine_constant_equals(mir.insns[25].dst, 0) ||
        mir.insns[27].src1 != mir.insns[22].dst ||
        mir.insns[27].src2 != mir.insns[25].dst ||
        mir.insns[27].phi_pred1 != mir.insns[21].label ||
        mir.insns[27].phi_pred2 != mir.insns[24].label ||
        mir.insns[28].src1 != mir.insns[27].dst ||
        mir.insns[28].label != mir.insns[48].label)
        return mir_machine_reject(
            "fortran-uppercase", "loop");
    if (mir.insns[31].src1 != mir.insns[1].dst ||
        mir.insns[31].src2 != mir.insns[9].dst ||
        mir.insns[31].immediate != 1 ||
        mir.insns[31].memory_size != 1 ||
        mir.insns[34].src1 != mir.insns[2].dst ||
        mir.insns[34].src2 != mir.insns[9].dst ||
        mir.insns[34].immediate != 1 ||
        mir.insns[34].memory_size != 1 ||
        mir.insns[35].src1 != mir.insns[34].dst ||
        mir.insns[35].memory_size != 1 ||
        mir.insns[36].src1 != mir.insns[35].dst ||
        mir.insns[37].src1 != mir.insns[36].dst ||
        !mir_machine_call_arguments(
            &mir.insns[39], 1, arguments) ||
        arguments[0] != mir.insns[37].dst ||
        (uppercase_function =
             mir_interpreter_file_function(39, 0, 1)) == NULL ||
        strcmp(asm_name_for(sym_asm_name(uppercase_function)),
               "__ctu") ||
        mir.insns[40].src1 != mir.insns[39].dst ||
        mir.insns[41].src1 != mir.insns[31].dst ||
        mir.insns[41].src2 != mir.insns[40].dst ||
        mir.insns[41].memory_size != 1)
        return mir_machine_reject(
            "fortran-uppercase", "conversion");
    if (!mir_machine_constant_equals(mir.insns[44].dst, 1) ||
        mir.insns[45].src1 != mir.insns[9].dst ||
        mir.insns[45].src2 != mir.insns[44].dst ||
        mir.insns[45].immediate != '+' ||
        mir.insns[46].src1 != mir.insns[45].dst ||
        mir.insns[47].label != mir.insns[6].label ||
        mir.insns[51].src1 != mir.insns[1].dst ||
        mir.insns[51].src2 != mir.insns[9].dst ||
        mir.insns[51].immediate != 1 ||
        mir.insns[51].memory_size != 1 ||
        !mir_machine_constant_equals(mir.insns[53].dst, 0) ||
        mir.insns[54].src1 != mir.insns[51].dst ||
        mir.insns[54].src2 != mir.insns[53].dst ||
        mir.insns[54].memory_size != 1)
        return mir_machine_reject(
            "fortran-uppercase", "completion");
    plan->limit = (int)limit;
    return 1;
}

static void mir_emit_fortran_uppercase_schedule(
    MirStream *out, const struct MirFortranUppercaseSchedule *plan)
{
    int loop = new_label();
    int store = new_label();
    int done = new_label();

    mir_stream_puts(MIR_EXACT_KERNEL_MARKER "\n"
          "\tld hl,2\n\tadd hl,sp\n"
          "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tinc hl\n\tld a,(hl)\n\tinc hl\n"
          "\tld h,(hl)\n\tld l,a\n", out);
    mir_stream_printf(out, "\tld b,%d\nL%d:\n", plan->limit, loop);
    mir_stream_puts("\tld a,(hl)\n\tor a\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n", done);
    mir_stream_puts("\tcp 97\n", out);
    mir_stream_printf(out, "\tjp c,L%d\n", store);
    mir_stream_puts("\tcp 123\n", out);
    mir_stream_printf(out, "\tjp nc,L%d\n\tsub 32\nL%d:\n"
            "\tld (de),a\n\tinc de\n\tinc hl\n"
            "\tdjnz L%d\nL%d:\n\txor a\n\tld (de),a\n\tret\n",
            store, store, loop, done);
}

static int mir_match_fortran_declaration_schedule(
    struct MirFortranDeclarationSchedule *plan)
{
    int instruction;

    memset(plan, 0, sizeof(*plan));
    if (mir.count != 394 || mir_cfg_block_count() != 68 ||
        mir.has_vla || mir.aggregate_temp_bytes != 0 ||
        (mir.return_type & 15) != TYPE_VOID)
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (insn->opcode !=
                mir_fortran_parse_decl_opcodes[instruction])
            return 0;
        if ((insn->opcode == MIR_LOAD_INDIRECT ||
             insn->opcode == MIR_STORE_INDIRECT) &&
            (insn->memory_flags & (1 | 8)) != 0)
            return 0;
    }
    if (!mir_machine_parameter_value_offset(
            mir.insns[1].dst, &plan->source_stack_offset) ||
        !mir_machine_parameter_value_offset(
            mir.insns[2].dst, &plan->type_stack_offset) ||
        plan->type_stack_offset != plan->source_stack_offset + 2 ||
        type_ptr_depth(mir.insns[1].type) != 1 ||
        type_size(mir.insns[1].type) != 2 ||
        type_size(mir.insns[2].type) != 2)
        return 0;
    plan->space_function =
        mir_interpreter_file_function(17, 0, 1);
    plan->alnum_function =
        mir_interpreter_file_function(107, 0, 1);
    plan->upper_function =
        mir_interpreter_file_function(159, 0, 1);
    plan->digit_function =
        mir_interpreter_file_function(274, 0, 1);
    plan->find_function =
        mir_interpreter_file_function(345, 0, 1);
    plan->add_function =
        mir_interpreter_file_function(357, 0, 4);
    if (plan->space_function == NULL ||
        plan->alnum_function == NULL ||
        plan->upper_function == NULL ||
        plan->digit_function == NULL ||
        plan->find_function == NULL ||
        plan->add_function == NULL ||
        !mir_interpreter_file_same_function(
            plan->space_function, 49, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->space_function, 201, 0, 1) ||
        !mir_interpreter_file_same_function(
            plan->space_function, 242, 0, 1))
        return 0;
    return 1;
}

static void mir_fortran_declaration_word_address(MirStream *out)
{
    mir_stream_puts("\tpush ix\n\tpop hl\n\tld de,-24\n\tadd hl,de\n",
          out);
}

static void mir_fortran_declaration_call_character(
    MirStream *out, struct Sym *function)
{
    mir_stream_puts("\tld l,(ix-34)\n\tld h,0\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, function);
    mir_stream_puts("\tpop bc\n", out);
}

static void mir_emit_fortran_declaration_schedule(
    MirStream *out, const struct MirFortranDeclarationSchedule *plan)
{
    int find_start = new_label();
    int outer = new_label();
    int separators = new_label();
    int separator_accept = new_label();
    int have_entry = new_label();
    int name_loop = new_label();
    int name_done = new_label();
    int name_accept = new_label();
    int name_no_store = new_label();
    int spaces = new_label();
    int no_array = new_label();
    int array_spaces = new_label();
    int digits = new_label();
    int digits_done = new_label();
    int close_scan = new_label();
    int close_done = new_label();
    int array_close_loop = new_label();
    int array_close_found = new_label();
    int no_add = new_label();
    int comma_scan = new_label();
    int done = new_label();

    mir_stream_puts(MIR_EXACT_KERNEL_MARKER "\n"
          "\tpush iy\n\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-34\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_stream_printf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tpush hl\n\tpop iy\nL%d:\n"
            "\tld a,(iy+0)\n\tor a\n\tjp z,L%d\n"
            "\tld (ix-34),a\n",
            plan->source_stack_offset + 4,
            plan->source_stack_offset + 5,
            find_start, outer);
    mir_fortran_declaration_call_character(
        out, plan->space_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n\tinc iy\n\tjp L%d\nL%d:\n",
            outer, find_start, outer);
    mir_stream_printf(out, "L%d:\n", separators);
    mir_stream_puts("\tld a,(iy+0)\n\tor a\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tld (ix-34),a\n", done);
    mir_fortran_declaration_call_character(
        out, plan->space_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", separator_accept);
    mir_stream_puts("\tld a,(ix-34)\n\tcp ','\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\nL%d:\n\tinc iy\n\tjp L%d\n"
            "L%d:\n\txor a\n\tld (ix-26),a\nL%d:\n",
            have_entry, separator_accept, separators,
            have_entry, name_loop);
    mir_stream_puts("\tld a,(iy+0)\n\tld (ix-34),a\n", out);
    mir_fortran_declaration_call_character(
        out, plan->alnum_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\n", name_accept);
    mir_stream_puts("\tld a,(ix-34)\n\tcp '_'\n", out);
    mir_stream_printf(out, "\tjp nz,L%d\nL%d:\n",
            name_done, name_accept);
    mir_stream_puts("\tld a,(ix-26)\n\tcp 23\n", out);
    mir_stream_printf(out, "\tjp nc,L%d\n", name_no_store);
    mir_stream_puts("\tld a,(ix-34)\n", out);
    mir_fortran_declaration_call_character(
        out, plan->upper_function);
    mir_stream_puts("\tld (ix-34),l\n", out);
    mir_fortran_declaration_word_address(out);
    mir_stream_puts("\tld e,(ix-26)\n\tld d,0\n\tadd hl,de\n"
          "\tld a,(ix-34)\n\tld (hl),a\n\tinc (ix-26)\n", out);
    mir_stream_printf(out, "L%d:\n\tinc iy\n\tjp L%d\nL%d:\n",
            name_no_store, name_loop, name_done);
    mir_fortran_declaration_word_address(out);
    mir_stream_puts("\tld e,(ix-26)\n\tld d,0\n\tadd hl,de\n\tld (hl),0\n"
          "\tld a,(ix-24)\n\tor a\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tld hl,1\n", done);
    mir_interpreter_file_store_ix_word(out, -30);
    mir_stream_puts("\tld hl,0\n", out);
    mir_interpreter_file_store_ix_word(out, -32);
    mir_stream_printf(out, "L%d:\n", spaces);
    mir_stream_puts("\tld a,(iy+0)\n\tor a\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tld (ix-34),a\n", no_array);
    mir_fortran_declaration_call_character(
        out, plan->space_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tinc iy\n\tjp L%d\nL%d:\n"
            "\tld a,(iy+0)\n\tcp '('\n\tjp nz,L%d\n\tinc iy\n"
            "L%d:\n",
            array_spaces, spaces, array_spaces, no_array,
            digits);
    mir_stream_puts("\tld a,(iy+0)\n\tor a\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tld (ix-34),a\n", digits_done);
    mir_fortran_declaration_call_character(
        out, plan->space_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n\tinc iy\n\tjp L%d\nL%d:\n",
            digits_done, digits, digits_done);
    mir_stream_puts("\tld hl,0\n", out);
    mir_interpreter_file_store_ix_word(out, -28);
    mir_stream_printf(out, "L%d:\n\tld a,(iy+0)\n\tld (ix-34),a\n",
            close_scan);
    mir_fortran_declaration_call_character(
        out, plan->digit_function);
    mir_stream_puts("\tld a,h\n\tor l\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n", close_done);
    mir_interpreter_file_load_ix_word(out, -28);
    mir_stream_puts("\tld de,0\n\tld e,l\n\tld d,h\n"
          "\tadd hl,hl\n\tadd hl,hl\n\tadd hl,de\n"
          "\tadd hl,hl\n\tld a,(ix-34)\n\tsub '0'\n"
          "\tld e,a\n\tld d,0\n\tadd hl,de\n", out);
    mir_interpreter_file_store_ix_word(out, -28);
    mir_stream_puts("\tinc iy\n", out);
    mir_stream_printf(out, "\tjp L%d\nL%d:\n", close_scan, close_done);
    mir_interpreter_file_load_ix_word(out, -28);
    mir_interpreter_file_store_ix_word(out, -32);
    mir_stream_puts("\tld hl,2\n", out);
    mir_interpreter_file_store_ix_word(out, -30);
    mir_stream_printf(out, "L%d:\n\tld a,(iy+0)\n\tor a\n"
            "\tjp z,L%d\n\tcp ')'\n\tjp z,L%d\n"
            "\tinc iy\n\tjp L%d\nL%d:\n"
            "\tld a,(iy+0)\n\tcp ')'\n\tjp nz,L%d\n\tinc iy\n"
            "L%d:\n",
            array_close_loop, no_array, array_close_found,
            array_close_loop, array_close_found,
            no_array, no_array);
    mir_fortran_declaration_word_address(out);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->find_function);
    mir_stream_puts("\tpop bc\n\tbit 7,h\n", out);
    mir_stream_printf(out, "\tjp z,L%d\n", no_add);
    mir_interpreter_file_load_ix_word(out, -32);
    mir_stream_puts("\tpush hl\n", out);
    mir_stream_printf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n",
            plan->type_stack_offset + 4,
            plan->type_stack_offset + 5);
    mir_interpreter_file_load_ix_word(out, -30);
    mir_stream_puts("\tpush hl\n", out);
    mir_fortran_declaration_word_address(out);
    mir_stream_puts("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->add_function);
    mir_interpreter_file_cleanup(out, 4);
    mir_stream_printf(out, "L%d:\nL%d:\n\tld a,(iy+0)\n\tor a\n"
            "\tjp z,L%d\n\tcp ','\n\tjp z,L%d\n"
            "\tinc iy\n\tjp L%d\n",
            no_add, comma_scan, done, separators, comma_scan);
    mir_stream_printf(out, "L%d:\n\tld sp,ix\n\tpop ix\n\tpop iy\n\tret\n",
            done);
}

static int mir_match_fortran_source_schedule(
    struct MirFortranSourceSchedule *plan)
{
    int instruction;

    memset(plan, 0, sizeof(*plan));
    if (mir.count != 337 || mir_cfg_block_count() != 51 ||
        mir.has_vla || mir.aggregate_temp_bytes != 0 ||
        (mir.return_type & 15) != TYPE_VOID)
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction)
        if (mir.insns[instruction].opcode !=
                mir_fortran_parse_source_opcodes[instruction])
            return 0;
    plan->length = mir_pascal_scan_symbol(11, 4, 0);
    plan->source = mir_pascal_scan_symbol(25, 2, 0);
    plan->trim_function =
        mir_interpreter_file_function(218, 0, 1);
    plan->digit_function =
        mir_interpreter_file_function(247, 0, 1);
    plan->space_function =
        mir_interpreter_file_function(288, 0, 1);
    plan->copy_function =
        mir_interpreter_file_function(311, 0, 2);
    plan->prefix_function =
        mir_interpreter_file_function(319, 0, 2);
    plan->append_function =
        mir_interpreter_file_function(332, 0, 3);
    plan->subroutine_string_id = (int)mir.insns[317].immediate;
    if (plan->length == NULL || plan->source == NULL ||
        plan->trim_function == NULL ||
        plan->digit_function == NULL ||
        plan->space_function == NULL ||
        plan->copy_function == NULL ||
        plan->prefix_function == NULL ||
        plan->append_function == NULL ||
        plan->subroutine_string_id < 0 ||
        !mir_pascal_scan_same_symbol(plan->length, 22) ||
        !mir_pascal_scan_same_symbol(plan->length, 69) ||
        !mir_pascal_scan_same_symbol(plan->length, 100) ||
        !mir_pascal_scan_same_symbol(plan->source, 55) ||
        !mir_pascal_scan_same_symbol(plan->source, 103) ||
        !mir_pascal_scan_same_symbol(plan->source, 130))
        return 0;
    return 1;
}

